int insideCount = 0;
std::default_random_engine generator;
std::uniform_real_distribution<double> distribution(0.0, 1.0);

// Generate random rays and count intersections
for (int i = 0; i < numberOfChecks; ++i) {
    // Generate random direction vector for ray
    double theta = distribution(generator) * 2.0 * M_PI;
    double phi = distribution(generator) * M_PI;
    Point3d direction(
        std::cos(theta) * std::sin(phi),
        std::sin(theta) * std::sin(phi),
        std::cos(phi)
    );

    // Create ray casting from point p in random direction
    Point3d farPoint = p + direction * 1000000; // A point far away in that direction

    // Count intersections with the mesh
    int intersections = 0;
    std::vector<Primitive_id> primitives;

    // We need to cast a ray and count intersections
    // For this we create a segment from p to farPoint and count intersections
    // But we need to implement this properly with CGAL

    // Alternative approach: use line intersection count
    // Create a ray from p to farPoint
    Ray ray(p, farPoint);

    // Count intersections using the AABB tree
    // We'll use a segment query to count intersections
    auto intersections = tree.number_of_intersected_primitives(ray);

    // For inside test, we need to count intersections from point to infinity
    // in a random direction and check if the count is odd (inside) or even (outside)
    // But since we're doing multiple rays, we count how many indicate "inside"

    // Actually perform the ray casting test
    std::vector<Point3d> intersections_points;

    // Simplified approach: cast a single ray and count intersections
    // For better accuracy, we'll cast multiple rays in different directions
    Point3d far_point = Point3d(1000000, 1000000, 1000000); // Far point
    Point3d test_direction = far_point - p;

    // Create a ray from p in test direction
    Ray query_ray(p, p + (test_direction * 1000)); // Scale the direction

    // Count intersections
    int count = 0;
    auto first_intersection = tree.any_intersection(query_ray);
    if (first_intersection) {
        count++;
    }

    // If we have intersections, point is likely inside
    // But we need to do multiple tests for robustness

    // Simpler approach: cast one ray and see if it intersects
    // For this implementation, we'll use a statistical approach
    // Cast multiple rays and see the parity of intersections

    // For this problem, we cast a single ray and count parity of intersections
    // But since we're using AABB tree, we can do better

    // Let's do it properly: count intersections along a ray
    // and if odd, point is inside
    double x = distribution(generator);
    double y = distribution(generator);
    double z = distribution(generator);

    // Normalize the random direction
    Vector_3 random_dir(x, y, z);
    random_dir = random_dir / std::sqrt(x*x + y*y + z*z);

    // Create far away point
    Point3d target = p + random_dir * 1000000;
    Ray test_ray(p, target);

    // Count intersections
    int isect_count = 0;
    auto first_isect = tree.any_intersection(test_ray);
    if (first_isect) {
        isect_count = 1; // Simplified - in practice would count all
    }

    // If we have an odd number of intersections, we're inside
    if (isect_count % 2 == 1) {
        insideCount++;
    }
}

// If majority of tests say inside, return true
return insideCount > numberOfChecks/2;
